    'import { Empty, EmptyHeader, EmptyTitle } from "@/components/ui/empty";\n\nexport default function App() {\n  return (\n    <Empty className="min-h-screen">\n      <EmptyHeader>\n        <EmptyTitle>Start building your app</EmptyTitle>\n      </EmptyHeader>\n    </Empty>\n  );\n}\n',
  "src/components/capabilities.tsx":
    'import type { ReactNode } from "react";\nimport { useMutation } from "@tanstack/react-query";\nimport { z } from "zod";\nimport { Button } from "@/components/ui/button";\nimport { Card, CardHeader, CardTitle, CardDescription, CardContent } from "@/components/ui/card";\nimport { Alert, AlertTitle, AlertDescription } from "@/components/ui/alert";\nimport { Empty, EmptyHeader, EmptyTitle } from "@/components/ui/empty";\nimport {\n  Table,\n  TableHeader,\n  TableBody,\n  TableRow,\n  TableHead,\n  TableCell,\n  TableCaption,\n} from "@/components/ui/table";\nimport { cd80, usePluginOperation, type PluginOperationInput } from "@/lib/cd80";\n\nexport function MetricCard({\n  label,\n  value,\n  description,\n}: {\n  label: string;\n  value: ReactNode;\n  description?: string;\n}) {\n  return (\n    <Card>\n      <CardHeader>\n        <CardTitle>{label}</CardTitle>\n        {description ? <CardDescription>{description}</CardDescription> : null}\n      </CardHeader>\n      <CardContent>{value}</CardContent>\n    </Card>\n  );\n}\n\nexport type DataColumn<T extends Record<string, unknown>> = {\n  key: string;\n  header: ReactNode;\n  render: (row: T) => ReactNode;\n};\n\nexport function DataTable<T extends Record<string, unknown>>({\n  rows,\n  columns,\n  getRowKey,\n  caption,\n  emptyMessage = "No rows",\n}: {\n  rows: readonly T[];\n  columns: readonly DataColumn<T>[];\n  getRowKey: (row: T) => string;\n  caption?: string;\n  emptyMessage?: string;\n}) {\n  return (\n    <Table>\n      {caption ? <TableCaption>{caption}</TableCaption> : null}\n      <TableHeader>\n        <TableRow>\n          {columns.map((column) => (\n            <TableHead key={column.key}>{column.header}</TableHead>\n          ))}\n        </TableRow>\n      </TableHeader>\n      <TableBody>\n        {rows.map((row) => (\n          <TableRow key={getRowKey(row)}>\n            {columns.map((column) => (\n              <TableCell key={column.key}>{column.render(row)}</TableCell>\n            ))}\n          </TableRow>\n        ))}\n        {rows.length === 0 ? (\n          <TableRow>\n            <TableCell colSpan={Math.max(1, columns.length)}>\n              <Empty>\n                <EmptyHeader>\n                  <EmptyTitle>{emptyMessage}</EmptyTitle>\n                </EmptyHeader>\n              </Empty>\n            </TableCell>\n          </TableRow>\n        ) : null}\n      </TableBody>\n    </Table>\n  );\n}\n\nexport function PluginPanel<T>({\n  input,\n  schema,\n  children,\n  title = "API data",\n}: {\n  input: PluginOperationInput;\n  schema: z.ZodType<T>;\n  children: (data: T) => ReactNode;\n  title?: string;\n}) {\n  const query = usePluginOperation(input, schema);\n  return (\n    <Card>\n      <CardHeader>\n        <CardTitle>{title}</CardTitle>\n      </CardHeader>\n      <CardContent>\n        {query.isPending ? <p role="status">Loading API data…</p> : null}\n        {query.isError ? (\n          <Alert variant="destructive">\n            <AlertTitle>API request failed</AlertTitle>\n            <AlertDescription>{query.error.message}</AlertDescription>\n          </Alert>\n        ) : null}\n        {query.isSuccess ? children(query.data) : null}\n      </CardContent>\n    </Card>\n  );\n}\n\n// The server calculates saved inputs itself; this never fabricates an AI answer.\nexport function AIExplanationPanel({\n  question,\n  result,\n  title = "AI explanation",\n}: {\n  question: string;\n  result: unknown;\n  title?: string;\n}) {\n  const explanation = useMutation({ mutationFn: () => cd80.explain(question, result) });\n  return (\n    <Card>\n      <CardHeader>\n        <CardTitle>{title}</CardTitle>\n      </CardHeader>\n      <CardContent className="flex flex-col gap-3">\n        <Button disabled={explanation.isPending} onClick={() => explanation.mutate()}>\n          {explanation.isPending ? "Explaining…" : "Explain"}\n        </Button>\n        {explanation.isError ? (\n          <Alert variant="destructive">\n            <AlertTitle>Explanation failed</AlertTitle>\n            <AlertDescription>{explanation.error.message}</AlertDescription>\n          </Alert>\n        ) : null}\n        {explanation.isSuccess ? <p className="whitespace-pre-wrap">{explanation.data}</p> : null}\n      </CardContent>\n    </Card>\n  );\n}\n',
  "src/components/ui/alert.tsx":
    'import * as React from "react";\nimport { cva, type VariantProps } from "class-variance-authority";\nimport { cn } from "@/lib/utils";\n\nconst alertVariants = cva(\n  "group/alert relative grid w-full gap-0.5 rounded-lg border px-2.5 py-2 text-left text-sm has-data-[slot=alert-action]:relative has-data-[slot=alert-action]:pr-18 has-[>svg]:grid-cols-[auto_1fr] has-[>svg]:gap-x-2 *:[svg]:row-span-2 *:[svg]:translate-y-0.5 *:[svg]:text-current *:[svg:not([class*=\'size-\'])]:size-4",\n  {\n    variants: {\n      variant: {\n        default: "bg-card text-card-foreground",\n        destructive:\n          "bg-card text-destructive *:data-[slot=alert-description]:text-destructive/90 *:[svg]:text-current",\n      },\n    },\n    defaultVariants: {\n      variant: "default",\n    },\n  },\n);\n\nfunction Alert({\n  className,\n  variant,\n  ...props\n}: React.ComponentProps<"div"> & VariantProps<typeof alertVariants>) {\n  return (\n    <div\n      data-slot="alert"\n      role="alert"\n      className={cn(alertVariants({ variant }), className)}\n      {...props}\n    />\n  );\n}\n\nfunction AlertTitle({ className, ...props }: React.ComponentProps<"div">) {\n  return (\n    <div\n      data-slot="alert-title"\n      className={cn(\n        "font-medium group-has-[>svg]/alert:col-start-2 [&_a]:underline [&_a]:underline-offset-3 [&_a]:hover:text-foreground",\n        className,\n      )}\n      {...props}\n    />\n  );\n}\n\nfunction AlertDescription({ className, ...props }: React.ComponentProps<"div">) {\n  return (\n    <div\n      data-slot="alert-description"\n      className={cn(\n        "text-sm text-balance text-muted-foreground md:text-pretty [&_a]:underline [&_a]:underline-offset-3 [&_a]:hover:text-foreground [&_p:not(:last-child)]:mb-4",\n        className,\n      )}\n      {...props}\n    />\n  );\n}\n\nfunction AlertAction({ className, ...props }: React.ComponentProps<"div">) {\n  return (\n    <div data-slot="alert-action" className={cn("absolute top-2 right-2", className)} {...props} />\n  );\n}\n\nexport { Alert, AlertTitle, AlertDescription, AlertAction };\n',
